	function SetMesh(part,meshid)	
		local args = {	
			[1] = "SyncMesh",	
			[2] = {	
				[1] = {	
					["Part"] = part,	
					["MeshId"] = "rbxassetid://"..meshid	
				}	
			}	
		}	
		_(args)	
	end	

	function SetTexture(part,texid)	
		local args = {	
			[1] = "SyncMesh",	
			[2] = {	
				[1] = {	
					["Part"] = part,	
					["TextureId"] = "rbxassetid://"..texid	
				}	
			}	
		}	
		_(args)	
	end	

	function SetVertexColor(part,color)	
		local args = {	
			[1] = "SyncMesh",	
			[2] = {	
				[1] = {	
					["Part"] = part,	
					["VertexColor"] = color	
				}	
			}	
		}	
		_(args)	
	end	

	function SetName(part,name)	
		local args = {	
			[1] = "SetName",	
			[2] = {part},	
			[3] = name	
		}	
		_(args)	
	end	

	function MeshResize(part,size)	
		local args = {	
			[1] = "SyncMesh",	
			[2] = {	
				[1] = {	
					["Part"] = part,	
					["Scale"] = size	
				}	
			}	
		}	
		_(args)	
	end	

	function SetLocked(part,bool)	
		local args = {	
			[1] = "SetLocked",	
			[2] = {part},	
			[3] = bool	
		}	
		_(args)	
	end	

	function Sky(id)	
		local root = char.HumanoidRootPart	
		local spawnPos = CFrame.new(	
			math.floor(root.Position.X),	
			math.floor(root.Position.Y),	
			math.floor(root.Position.Z)	
		) + Vector3.new(0,6,0)	

		CreatePart(spawnPos,workspace)	
		task.wait(0.2)	

		local skyPart	
		for i,v in workspace:GetDescendants() do	
			if v:IsA("BasePart") and (v.Position - spawnPos.Position).Magnitude < 1 then	
				skyPart = v	

				SetName(v,"HdSkyboxTrippy")	
				AddMesh(v)	
				SetMesh(v,"111891702759441")	
				SetTexture(v,id)	


				SetVertexColor(v, Vector3.new(3,3,3))	

				MeshResize(v,Vector3.new(3000,3000,3000))	
				SetLocked(v,true)	
				SetAnchor(true,v)	
				SetCollision(v,false)	
				break	
			end	
		end	

		if skyPart then	
			local t = 0	
			local baseSpeed = 0	
			local randomness = 0	

			game:GetService("RunService").Heartbeat:Connect(function(dt)	
				t = t + dt	
				local rotX = math.sin(t * 1.5) * randomness	
				local rotY = t * baseSpeed	
				local rotZ = math.cos(t * 2.1) * randomness	
				local newCf = spawnPos * CFrame.Angles(	
					math.rad(rotX),	
					math.rad(rotY),	
					math.rad(rotZ)	
				)	
				MovePart(skyPart,newCf)	
			end)	
		end	
	end	

	Sky("139499765179442")	
	end)	
end;
